var i=`0648-soupou-kandja`;var t=`world-0648`;var a=`SN`;var o=`western-africa`;var s=4;var r=61;var l={en:`Soupou Kandja`,ua:`Супу канджа`};var g={en:`Soupou Kandja is a Senegal classic prepared with beef chuck, yellow onion, okra, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Супу канджа, страва кухні країни Сенегал зі складниками: яловича лопатка, жовта цибуля, бамія, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,500,`g`],[`red-palm-oil`,55,`ml`],[`yellow-onion`,160,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`okra`,420,`g`],[`tomato`,290,`g`],[`canned-tuna`,180,`g`],[`water`,620,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon-juice`,24,`ml`],[`parsley`,15,`g`]]}];var d={slug:i,id:t,country:`SN`,region:o,servings:4,minutes:61,title:l,text:g,steps:u};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,i as slug,u as steps,g as text,l as title};